SELECT id, name
FROM series_group
WHERE user_id = #{userId} AND id = #{id}

SELECT id, name
FROM series_group
WHERE user_id = #{userId} AND name = #{name}

mapper.insert:
INSERT INTO figure_series (user_id, figure_id, series_id)
SELECT DISTINCT l.user_id, l.figure_id, #{fallbackId}
FROM figure_series l
WHERE l.user_id = #{userId}
  AND l.series_id IN (SELECT id FROM series WHERE user_id = #{userId} AND group_id = #{id})
  AND NOT EXISTS (
      SELECT 1 FROM figure_series o
      WHERE o.user_id = l.user_id AND o.figure_id = l.figure_id
        AND o.series_id NOT IN (SELECT id FROM series WHERE user_id = #{userId} AND group_id = #{id})
  )

mapper.delete:
DELETE FROM figure_series
WHERE user_id = #{userId}
  AND series_id IN (SELECT id FROM series WHERE user_id = #{userId} AND group_id = #{id})
